def min_sum_of_lengths(arr, target):
    n = len(arr)
    matches = []
    for start in range(n):
        total = 0
        for end in range(start, n):
            total += arr[end]                                              # extend the subarray by one and recompute its sum directly
            if total == target:
                matches.append((start, end))
    best = float('inf')
    for i in range(len(matches)):
        for j in range(len(matches)):
            s1, e1 = matches[i]
            s2, e2 = matches[j]
            if e1 < s2 or e2 < s1:                                          # the two subarrays must not overlap at all
                length = (e1 - s1 + 1) + (e2 - s2 + 1)
                best = min(best, length)
    return best if best != float('inf') else -1


if __name__ == "__main__":
    print(min_sum_of_lengths([3, 2, 2, 4, 3], 3))

