import java.util.*;

public class Main {
    int minSumOfLengths(int[] arr, int target) {
        int n = arr.length;
        List<int[]> matches = new ArrayList<>();
        for (int start = 0; start < n; start++) {
            int total = 0;
            for (int end = start; end < n; end++) {
                total += arr[end];                                               // extend the subarray by one and recompute its sum directly
                if (total == target) matches.add(new int[]{start, end});
            }
        }
        int best = Integer.MAX_VALUE;
        for (int[] m1 : matches) {
            for (int[] m2 : matches) {
                if (m1[1] < m2[0] || m2[1] < m1[0]) {                              // the two subarrays must not overlap at all
                    int length = (m1[1] - m1[0] + 1) + (m2[1] - m2[0] + 1);
                    best = Math.min(best, length);
                }
            }
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minSumOfLengths(new int[]{3, 2, 2, 4, 3}, 3));
    }
}

