int minSumOfLengths(vector<int>& arr, int target) {
    int n = (int)arr.size();
    vector<pair<int,int>> matches;
    for (int start = 0; start < n; start++) {
        int total = 0;
        for (int end = start; end < n; end++) {
            total += arr[end];                                                 // extend the subarray by one and recompute its sum directly
            if (total == target) matches.push_back({start, end});
        }
    }
    int best = INT_MAX;
    for (auto& m1 : matches) {
        for (auto& m2 : matches) {
            if (m1.second < m2.first || m2.second < m1.first) {                  // the two subarrays must not overlap at all
                int length = (m1.second - m1.first + 1) + (m2.second - m2.first + 1);
                best = min(best, length);
            }
        }
    }
    return best == INT_MAX ? -1 : best;
}

