import java.util.*;

public class Main {
    int minSumOfLengths(int[] arr, int target) {
        int n = arr.length;
        int[] bestEndingAtOrBefore = new int[n];                                  // shortest valid subarray ending anywhere from 0 up to this index
        Arrays.fill(bestEndingAtOrBefore, Integer.MAX_VALUE);
        int left = 0;
        int total = 0;
        int runningBest = Integer.MAX_VALUE;
        int answer = Integer.MAX_VALUE;
        for (int right = 0; right < n; right++) {
            total += arr[right];
            while (total > target) {                                               // all values are positive, so shrinking only ever decreases the sum
                total -= arr[left];
                left++;
            }
            if (total == target) {
                int length = right - left + 1;
                if (left > 0 && bestEndingAtOrBefore[left - 1] != Integer.MAX_VALUE) {
                    answer = Math.min(answer, bestEndingAtOrBefore[left - 1] + length);   // combine with the best NON-OVERLAPPING match found so far
                }
                runningBest = Math.min(runningBest, length);
            }
            bestEndingAtOrBefore[right] = runningBest;
        }
        return answer == Integer.MAX_VALUE ? -1 : answer;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minSumOfLengths(new int[]{3, 2, 2, 4, 3}, 3));
    }
}

